import React, { useState } from 'react';
import './styles.css';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductCatalog from './components/ProductCatalog';
import CartDrawer from './components/CartDrawer';
import Footer from './components/Footer';

export default function App() {
  const [cart, setCart] = useState([
    {
      id: 1,
      name: 'Structured Linen Overshirt',
      price: 240,
      quantity: 1,
      image: 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=600&q=80',
      category: 'Apparel',
      size: 'M'
    }
  ]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  const handleAddToCart = (product, selectedSize = 'M') => {
    setCart(prev => {
      const existingIndex = prev.findIndex(item => item.id === product.id && item.size === selectedSize);
      if (existingIndex > -1) {
        const updated = [...prev];
        updated[existingIndex].quantity += 1;
        return updated;
      }
      return [...prev, { ...product, quantity: 1, size: selectedSize }];
    });
    setIsCartOpen(true);
  };

  const handleUpdateQuantity = (id, size, delta) => {
    setCart(prev => {
      return prev
        .map(item => {
          if (item.id === id && item.size === size) {
            const newQty = item.quantity + delta;
            return newQty > 0 ? { ...item, quantity: newQty } : null;
          }
          return item;
        })
        .filter(Boolean);
    });
  };

  const handleRemoveItem = (id, size) => {
    setCart(prev => prev.filter(item => !(item.id === id && item.size === size)));
  };

  const totalItemsCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className='min-h-screen flex flex-col bg-[#fcfbf9] text-[#111111]'>
      <Header 
        cartCount={totalItemsCount} 
        onOpenCart={() => setIsCartOpen(true)} 
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      />

      <main className='flex-grow'>
        <Hero onExplore={() => {
          const element = document.getElementById('catalog-section');
          if (element) element.scrollIntoView({ behavior: 'smooth' });
        }} />

        <div id='catalog-section'>
          <ProductCatalog 
            selectedCategory={selectedCategory}
            setSelectedCategory={setSelectedCategory}
            searchQuery={searchQuery}
            onAddToCart={handleAddToCart}
          />
        </div>
      </main>

      <CartDrawer 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        onUpdateQuantity={handleUpdateQuantity}
        onRemoveItem={handleRemoveItem}
      />

      <Footer />
    </div>
  );
}

