  const handleCheckout = () => {
    setIsCheckingOut(true);
    setTimeout(() => {
      setIsCheckingOut(false);
      setOrderComplete(true);
      clearCart();
    }, 1500);
  };

  const handleReset = () => {
    setOrderComplete(false);
    onClose();
  };

  return (
    <div className='fixed inset-0 z-50 overflow-hidden'>
      <div 
        className='absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity'
        onClick={onClose}
        aria-hidden='true'
      />

      <div className='absolute inset-y-0 right-0 max-w-full flex pl-10'>
        <div className='w-screen max-w-md bg-[#fcfbf9] shadow-2xl flex flex-col'>

          {/* Drawer Header */}
          <div className='flex items-center justify-between px-6 py-5 border-b border-[#e5e5e0]'>
            <div className='flex items-center gap-2'>
              <ShoppingBag className='w-5 h-5 text-[#111111]' />
              <h2 className='font-heading text-lg font-bold tracking-tight text-[#111111]'>
                Your Cart {cart.length > 0 && `(${cart.reduce((a, c) => a + c.quantity, 0)})`}
              </h2>
            </div>
            <button 
              onClick={onClose}
              className='p-2 text-[#737373] hover:text-[#111111] transition-colors rounded-none'
              aria-label='Close cart'
            >
              <X className='w-5 h-5' />
            </button>
          </div>

          {/* Body Content */}
          <div className='flex-1 overflow-y-auto px-6 py-4'>
            {orderComplete ? (
              <div className='h-full flex flex-col items-center justify-center text-center py-12 animate-fade-in'>
                <div className='w-16 h-16 bg-[#111111] text-[#fcfbf9] rounded-none flex items-center justify-center mb-6'>
                  <CheckCircle2 className='w-8 h-8' />
                </div>
                <h3 className='font-heading text-2xl font-bold mb-2 text-[#111111]'>Order Confirmed</h3>
                <p className='text-[#737373] text-sm max-w-xs mb-8'>
                  Thank you for your acquisition. We are carefully preparing your order for shipment.
                </p>
                <button
                  onClick={handleReset}
                  className='w-full py-4 bg-[#111111] text-[#fcfbf9] font-medium text-sm tracking-wider uppercase hover:bg-neutral-800 transition-colors rounded-none'
                >
                  Continue Shopping
                </button>
              </div>
            ) : cart.length === 0 ? (
              <div className='h-full flex flex-col items-center justify-center text-center py-12'>
                <div className='w-16 h-16 bg-[#e5e5e0] text-[#737373] rounded-none flex items-center justify-center mb-4'>
                  <ShoppingBag className='w-6 h-6' />
                </div>
                <p className='font-heading text-lg font-bold mb-1 text-[#111111]'>Your cart is empty</p>
                <p className='text-[#737373] text-sm mb-6'>Discover our curation of refined lifestyle pieces.</p>
                <button
                  onClick={onClose}
                  className='px-6 py-3 bg-[#111111] text-[#fcfbf9] text-xs font-semibold uppercase tracking-wider hover:bg-neutral-800 transition-colors rounded-none'
                >
                  Explore Collection
                </button>
              </div>
            ) : (
              <div className='divide-y divide-[#e5e5e0]'>
                {cart.map((item) => (
                  <div key={`${item.id}-${item.selectedSize || 'standard'}`} className='py-4 flex gap-4 items-start group'>
                    <div className='w-20 h-24 bg-[#ffffff] border border-[#e9e8e2] overflow-hidden flex-shrink-0'>
                      <img 
                        src={item.image} 
                        alt={item.name} 
                        className='w-full h-full object-cover group-hover:scale-105 transition-transform duration-500'
                      />
                    </div>
                    <div className='flex-1 min-w-0'>
                      <div className='flex justify-between items-start'>
                        <h4 className='font-heading font-bold text-sm text-[#111111] truncate pr-2'>
                          {item.name}
                        </h4>
                        <button 
                          onClick={() => removeItem(item.id, item.selectedSize)}
                          className='text-[#737373] hover:text-red-600 transition-colors p-1'
                          title='Remove item'
                        >
                          <Trash2 className='w-4 h-4' />
                        </button>
                      </div>
                      {item.selectedSize && (
                        <p className='text-xs text-[#737373] mt-0.5'>Size: <span className='uppercase font-medium text-[#111111]'>{item.selectedSize}</span></p>
                      )}
                      <p className='text-sm font-semibold text-[#111111] mt-1'>
                        ${item.price.toFixed(2)}
                      </p>

                      <div className='flex items-center justify-between mt-3'>
                        <div className='flex items-center border border-[#e5e5e0] bg-[#ffffff]'>
                          <button
                            onClick={() => updateQuantity(item.id, item.selectedSize, item.quantity - 1)}
                            className='p-1.5 text-[#737373] hover:text-[#111111] transition-colors'
                            aria-label='Decrease quantity'
                          >
                            <Minus className='w-3 h-3' />
                          </button>
                          <span className='px-3 text-xs font-medium text-[#111111]'>
                            {item.quantity}
                          </span>
                          <button
                            onClick={() => updateQuantity(item.id, item.selectedSize, item.quantity + 1)}
                            className='p-1.5 text-[#737373] hover:text-[#111111] transition-colors'
                            aria-label='Increase quantity'
                          >
                            <Plus className='w-3 h-3' />
                          </button>
                        </div>
                        <span className='text-xs font-semibold text-[#111111]'>
                          ${(item.price * item.quantity).toFixed(2)}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Drawer Footer */}
          {!orderComplete && cart.length > 0 && (
            <div className='border-t border-[#e5e5e0] px-6 py-5 bg-[#fcfbf9]'>
              <div className='space-y-2 mb-4 text-sm'>
                <div className='flex justify-between text-[#737373]'>
                  <span>Subtotal</span>
                  <span className='text-[#111111] font-medium'>${subtotal.toFixed(2)}</span>
                </div>
                <div className='flex justify-between text-[#737373]'>
                  <span>Shipping {subtotal > 150 && '(Free over $150)'}</span>
                  <span className='text-[#111111] font-medium'>
                    {shipping === 0 ? 'Complimentary' : `$${shipping.toFixed(2)}`}
                  </span>
                </div>
                <div className='pt-2 border-t border-[#e5e5e0] flex justify-between text-base font-bold text-[#111111]'>
                  <span>Total</span>
                  <span>${total.toFixed(2)}</span>
                </div>
              </div>

              <button
                onClick={handleCheckout}
                disabled={isCheckingOut}
                className='w-full py-4 bg-[#111111] text-[#fcfbf9] text-xs font-bold uppercase tracking-widest hover:bg-neutral-800 transition-colors flex items-center justify-center gap-2 rounded-none disabled:opacity-50'
              >
                {isCheckingOut ? (
                  <span className='flex items-center gap-2'>
                    <span className='w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin' />
                    Processing Secure Checkout...
                  </span>
                ) : (
                  <span className='flex items-center gap-2'>
                    Proceed to Checkout <ArrowRight className='w-4 h-4' />
                  </span>
                )}
              </button>

              <p className='text-center text-[10px] text-[#737373] mt-3'>
                Secure 256-bit SSL Encryption • Free Returns Within 30 Days
              </p>
            </div>
          )}

        </div>
      </div>
    </div>
  );
}
